local function f1(V) return ("(%.1f, %.1f, %.1f)"):format(V.X, V.Y, V.Z) end
local function cf(T) return CFrame.new(table.unpack(T)) end
local function v3(T) return Vector3.new(T[1], T[2], T[3]) end
local function leaf(Path) return Path:match("([^/]+)$") end
local function parentPath(Path) return Path:match("^(.*)/[^/]+$") end
local function depth(Path) return select(2, Path:gsub("/", "")) end

-- the world box of a part (any rotation)
local function aabb(P)
	local C, S = P.CFrame, P.Size / 2
	local R, U, L = C.RightVector, C.UpVector, C.LookVector
	local H = Vector3.new(
		math.abs(R.X) * S.X + math.abs(U.X) * S.Y + math.abs(L.X) * S.Z,
		math.abs(R.Y) * S.X + math.abs(U.Y) * S.Y + math.abs(L.Y) * S.Z,
		math.abs(R.Z) * S.X + math.abs(U.Z) * S.Y + math.abs(L.Z) * S.Z)
	return C.Position - H, C.Position + H
end
-- the flat distance from (x, z) to a part's box
local function boxDist(P, X, Z)
	local Lo, Hi = aabb(P)
	local DX = math.max(Lo.X - X, 0, X - Hi.X)
	local DZ = math.max(Lo.Z - Z, 0, Z - Hi.Z)
	return math.sqrt(DX * DX + DZ * DZ)
end
local function insideSF(V) return V.X > SF_BOX.X0 and V.X < SF_BOX.X1 and V.Z > SF_BOX.Z0 and V.Z < SF_BOX.Z1 end

-- the kit's pieces by group, the Ward, the containers by "Group|Path"
local function kitPieces(Group)
	local Out = {}
	for _, P in ipairs(KIT.Pieces) do if P.Group == Group then table.insert(Out, P) end end
	return Out
end
local Containers = {}
for _, M in ipairs(KIT.Models) do Containers[M.Group .. "|" .. M.Path] = M end
local function hasTag(Piece, Tag) return table.find(Piece.Tags, Tag) ~= nil end
-- where a kit piece goes in Foundry
local function target(Piece)
	if Piece.Group == "SilentForge" then
		if hasTag(Piece, "RenseiArea") then return AREA_CF end
		return T_SF * cf(Piece.CFrame)
	elseif Piece.Group == "ForgeFloor" then return MARKER_CF
	elseif Piece.Group == "Brannoc" then return cf(Piece.CFrame) + PROP_SHIFT end
	error("no target for group " .. tostring(Piece.Group))
end
local function sizeOf(Piece)
	if Piece.Group == "SilentForge" and hasTag(Piece, "RenseiArea") then return AREA_SIZE end
	return v3(Piece.Size)
end

-- the shell parts a piece must not touch: the great hall's SilentForge* / ForgeFloor* parts but the two floors
local function shellParts()
	local L = {}
	for _, P in ipairs(GH:GetDescendants()) do
		if P:IsA("BasePart") and (P.Name:match("^SilentForge") or P.Name:match("^ForgeFloor")) and P ~= SFFloor and P ~= FFFloor then
			table.insert(L, P)
		end
	end
	return L
end
local function trainerSpot()
	local L = {}
	for _, P in ipairs(CS:GetTagged("RenseiMarker")) do
		if P:IsDescendantOf(workspace) and P:GetAttribute("Piece") == "TrainerSpot" and P:GetAttribute("Element") == "Metal" then table.insert(L, P) end
	end
	return #L == 1 and L[1] or nil, #L
end
-- tagged instances in workspace (any code reading a tag ignores instances outside workspace)
local function tagged(Tag, Under)
	local L = {}
	for _, I in ipairs(CS:GetTagged(Tag)) do
		if I:IsDescendantOf(Under or workspace) then table.insert(L, I) end
	end
	return L
end
local function trainerMetal()
	for _, D in ipairs(workspace:GetDescendants()) do
		if D:IsA("Model") and D:GetAttribute("DialogueId") == "trainer_metal" then return D end
	end
end

-- ------------------------------------------------------------------ mesh sources
local MeshCache = {}
local function meshSource(MeshId)
	if MeshCache[MeshId] then return MeshCache[MeshId][1], MeshCache[MeshId][2] end
	local Src, Why
	local Assets = game.ReplicatedStorage:FindFirstChild("Assets")
	if Assets then
		for _, D in ipairs(Assets:GetDescendants()) do
			if D:IsA("MeshPart") and D.MeshId == MeshId then Src, Why = D, "Assets clone (" .. D:GetFullName() .. ")" break end
		end
	end
	if not Src and MODE ~= "plan" then
		local Ok, M = pcall(function() return AssetService:CreateMeshPartAsync(MeshId) end)
		if Ok and M then Src, Why = M, "CreateMeshPartAsync" else Why = "no Assets MeshPart, CreateMeshPartAsync failed: " .. tostring(M) end
	elseif not Src then
		Why = "no Assets MeshPart (apply would try CreateMeshPartAsync)"
	end
	MeshCache[MeshId] = {Src, Why}
	return Src, Why
end

-- ------------------------------------------------------------------ the Ward spot tests
local rpG = RaycastParams.new()
rpG.FilterType = Enum.RaycastFilterType.Exclude
rpG.RespectCanCollide = true
-- the ground under (x, z): a ray down from y 15; returns the hit part and its top
local function groundAt(X, Z, Skip)
	rpG.FilterDescendantsInstances = Skip or {}
	local Hit = workspace:Raycast(Vector3.new(X, 15, Z), Vector3.new(0, -30, 0), rpG)
	if not Hit then return nil, nil end
	return Hit.Instance, Hit.Position.Y
end
local function wardSpotTest(At, Skip)
	local Hit, Top = groundAt(At.X, At.Z, Skip)
	if Hit ~= SFFloor then return false, "the ground ray meets " .. (Hit and Hit:GetFullName() or "nothing") .. ", not SilentForgeFloor" end
	if Top < WARD_TOP_LO or Top > WARD_TOP_HI then return false, ("the floor top %.2f is not %.1f..%.1f"):format(Top, WARD_TOP_LO, WARD_TOP_HI) end
	local Op = OverlapParams.new()
	Op.FilterType = Enum.RaycastFilterType.Exclude
	Op.FilterDescendantsInstances = Skip or {}
	local Solid = {}
	for _, P in ipairs(workspace:GetPartBoundsInBox(CFrame.new(At.X, Top + 0.05 + WARD_BOX.Y / 2, At.Z), WARD_BOX, Op)) do
		if P.CanCollide then table.insert(Solid, P.Name) end
	end
	if #Solid > 0 then return false, "solid in the 4 x 5 x 4 box over it [" .. table.concat(Solid, ",") .. "]" end
	return true, ("floor top %.2f, box clear"):format(Top)
end

-- ------------------------------------------------------------------ check (a failure list)
local function checks()
	local Fails, Passes, Out = 0, 0, {}
	local function cond(Failed, What)
		if Failed then
			Fails += 1
			table.insert(Out, "  FAIL " .. What)
		else
			Passes += 1
		end
	end
	local Rooms = FD:FindFirstChild("ForgeRooms")
	local SFm = Rooms and Rooms:FindFirstChild("SilentForge")
	local FFm = Rooms and Rooms:FindFirstChild("ForgeFloor")
	cond(not (Rooms and Rooms:IsA("Model")), "no Model Map.Foundry.ForgeRooms")
	cond(not (SFm and SFm:IsA("Model") and FFm and FFm:IsA("Model")), "ForgeRooms has no SilentForge and ForgeFloor sub-models")
	cond(FD:GetAttribute(FLAG) ~= "applied", FLAG .. " is " .. tostring(FD:GetAttribute(FLAG)) .. ", not applied")

	-- (1) every kit piece in place (against the kit's Ye CFrames through T_SF)
	local Placed = {}
	for _, Piece in ipairs(KIT.Pieces) do
		if Piece.Group ~= "Brannoc" then
			local Root = Piece.Group == "SilentForge" and SFm or FFm
			local Want = target(Piece)
			local Found
			if Root then
				for _, I in ipairs(Root:GetDescendants()) do
					if not Placed[I] and I:IsA("BasePart") and I.Name == leaf(Piece.Path) and I.ClassName == Piece.Class
						and (I.Position - Want.Position).Magnitude <= 0.05 and I.CFrame.LookVector:Dot(Want.LookVector) > 0.999 then
						Found = I
						break
					end
				end
			end
			if Found then Placed[Found] = true end
			cond(not Found, ("%s/%s (%s) not at %s"):format(Piece.Group, Piece.Path, Piece.Class, f1(Want.Position)))
		end
	end

	-- (2) Ruling 4: the fit and touch checks, colliding furniture only (not the RenseiArea box, not CanCollide false)
	local Shell = shellParts()
	local OpShell = OverlapParams.new()
	OpShell.FilterType = Enum.RaycastFilterType.Include
	OpShell.FilterDescendantsInstances = Shell
	local WantSolid = 0
	for _, Piece in ipairs(kitPieces("SilentForge")) do
		if Piece.CanCollide and not hasTag(Piece, "RenseiArea") then WantSolid += 1 end
	end
	local Solid = 0
	for _, P in ipairs(SFm and SFm:GetDescendants() or {}) do
		if P:IsA("BasePart") and P.CanCollide and not CS:HasTag(P, "RenseiArea") then
			Solid += 1
			local Lo, Hi = aabb(P)
			-- (flat: the kit's DriveShaft stands through the floor, as it did in Ye: y 2.3..8.3 over a floor at 4.7)
			cond(not (Lo.X >= SF_BOX.X0 + INSET and Hi.X <= SF_BOX.X1 - INSET and Lo.Z >= SF_BOX.Z0 + INSET and Hi.Z <= SF_BOX.Z1 - INSET),
				("%s's box x %.1f..%.1f z %.1f..%.1f is not inside the interior (inset %.1f)"):format(P.Name, Lo.X, Hi.X, Lo.Z, Hi.Z, INSET))
			local Hits = {}
			for _, H in ipairs(workspace:GetPartsInPart(P, OpShell)) do table.insert(Hits, H.Name) end
			cond(#Hits > 0, P.Name .. " touches the shell [" .. table.concat(Hits, ",") .. "]")
		end
	end
	cond(Solid ~= WantSolid, ("%d colliding Silent Forge pieces, not the kit's %d"):format(Solid, WantSolid))

	-- (3) the area box is the room's interior
	local Areas = Rooms and tagged("RenseiArea", Rooms) or {}
	local Area = #Areas == 1 and Areas[1] or nil
	cond(not (Area and Area:GetAttribute("AreaName") == "Silent Forge"), "ForgeRooms has not exactly one RenseiArea named Silent Forge")
	if Area then
		cond((Area.Position - AREA_CF.Position).Magnitude > AREA_EPS, "the Silent ForgeArea box is at " .. f1(Area.Position) .. ", not " .. f1(AREA_CF.Position))
		local D = Area.Size - AREA_SIZE
		cond(math.max(math.abs(D.X), math.abs(D.Y), math.abs(D.Z)) > AREA_EPS, "the Silent ForgeArea box is " .. f1(Area.Size) .. ", not " .. f1(AREA_SIZE))
	end

	-- (4) the counts in ForgeRooms
	local function ids(Tag, Attr)
		local L = {}
		for _, I in ipairs(Rooms and tagged(Tag, Rooms) or {}) do table.insert(L, tostring(I:GetAttribute(Attr))) end
		table.sort(L)
		return table.concat(L, ",")
	end
	local WantInspect = table.clone(INSPECTS)
	table.sort(WantInspect)
	cond(ids("RenseiInspect", "InspectId") ~= table.concat(WantInspect, ","), "ForgeRooms' RenseiInspect ids are [" .. ids("RenseiInspect", "InspectId") .. "], not the 4 metal_* ids")
	cond(ids("RenseiMechanism", "MechanismId") ~= "metal_bench", "ForgeRooms' RenseiMechanism ids are [" .. ids("RenseiMechanism", "MechanismId") .. "], not metal_bench")
	cond(ids("RenseiTrial", "TrialId") ~= "metal_experiment", "ForgeRooms' RenseiTrial ids are [" .. ids("RenseiTrial", "TrialId") .. "], not metal_experiment")
	cond(ids("RenseiArea", "AreaName") ~= "Silent Forge", "ForgeRooms' RenseiArea names are [" .. ids("RenseiArea", "AreaName") .. "], not Silent Forge")
	cond(ids("RenseiEnemySpawn", "EnemyType") ~= "WardAlchemist", "ForgeRooms' RenseiEnemySpawn types are [" .. ids("RenseiEnemySpawn", "EnemyType") .. "], not WardAlchemist")
	-- (5) workspace's areas
	cond(#tagged("RenseiArea") ~= AREA_COUNT, ("%d RenseiArea in workspace, not %d"):format(#tagged("RenseiArea"), AREA_COUNT))

	-- (6) Brannoc
	local Folder = NPCs:FindFirstChild("Alchemy Trainers")
	local B = Folder and Folder:FindFirstChild("Metal Alchemist")
	local BRoot = B and B:FindFirstChild("HumanoidRootPart")
	cond(not (B and B:IsA("Model") and BRoot), "no World.NPCs[\"Alchemy Trainers\"][\"Metal Alchemist\"] with a HumanoidRootPart")
	cond(not (B and B:GetAttribute("DialogueId") == "trainer_metal"), "Brannoc's DialogueId is not trainer_metal")
	local Spot, NSpot = trainerSpot()
	cond(not Spot, NSpot .. " Metal TrainerSpot markers in workspace, not 1")
	if BRoot then
		cond((BRoot.Position - BRANNOC_CF.Position).Magnitude > BRANNOC_NEAR, "Brannoc's root is at " .. f1(BRoot.Position) .. ", not within 0.5 of " .. f1(BRANNOC_CF.Position))
		cond(not (BRoot.CFrame.LookVector.Z < -0.99), ("Brannoc faces (%.2f, %.2f, %.2f), not -Z"):format(BRoot.CFrame.LookVector.X, BRoot.CFrame.LookVector.Y, BRoot.CFrame.LookVector.Z))
		if Spot then cond((BRoot.Position - Spot.Position).Magnitude > SPOT_NEAR, ("Brannoc stands %.1f from the TrainerSpot (over %d)"):format((BRoot.Position - Spot.Position).Magnitude, SPOT_NEAR)) end
	end

	-- (7) the trial marker at the Forge Floor's centre, its bottom on the floor, facing -Z
	local Trials = Rooms and tagged("RenseiTrial", Rooms) or {}
	local M = #Trials == 1 and Trials[1] or nil
	if M then
		local FloorTop = FFFloor.Position.Y + FFFloor.Size.Y / 2
		cond(not (M.Parent == FFm and math.abs(M.Position.X - FFFloor.Position.X) <= 0.05 and math.abs(M.Position.Z - FFFloor.Position.Z) <= 0.05
			and math.abs(M.Position.Y - M.Size.Y / 2 - FloorTop) <= 0.05 and (M.Position - MARKER_CF.Position).Magnitude <= 0.05
			and M.CFrame.LookVector.Z < -0.99),
			"the trial marker at " .. f1(M.Position) .. " is not in ForgeRooms.ForgeFloor at the Forge Floor's centre, on its floor, facing -Z")
	else
		cond(true, "no single trial marker in ForgeRooms")
	end

	-- (8) the Ward spawn
	local Wards = Rooms and tagged("RenseiEnemySpawn", Rooms) or {}
	local W = #Wards == 1 and Wards[1] or nil
	if W then
		cond(not (W.Parent == SFm and W:GetAttribute("EnemyType") == "WardAlchemist" and W:GetAttribute("Weapon") == ""),
			"the Ward spawn is not in ForgeRooms.SilentForge with EnemyType WardAlchemist and Weapon \"\"")
		cond(not insideSF(W.Position), "the Ward spawn at " .. f1(W.Position) .. " is not inside the Silent Forge interior")
		local Hit, Top = groundAt(W.Position.X, W.Position.Z, {W})
		cond(not (Hit == SFFloor and W.Position.Y - Top <= WARD_GROUND and W.Position.Y - Top >= 0),
			("the Ward spawn's ground ray meets %s%s, not SilentForgeFloor within %.1f"):format(Hit and Hit.Name or "nothing", Top and (" %.2f under it"):format(W.Position.Y - Top) or "", WARD_GROUND))
		local DD = (Vector2.new(W.Position.X, W.Position.Z) - DOOR).Magnitude
		cond(DD < DOOR_CLEAR, ("the Ward spawn is %.1f from the doorway's centre (under %d)"):format(DD, DOOR_CLEAR))
		local HD = boxDist(Hearth, W.Position.X, W.Position.Z)
		cond(HD < HEARTH_CLEAR, ("the Ward spawn is %.1f from the hearth's box (under %d)"):format(HD, HEARTH_CLEAR))
	else
		cond(true, "no single Ward spawn in ForgeRooms")
	end

	return Fails, ("check: PASS %d / FAIL %d"):format(Passes, Fails), Out
end

-- ------------------------------------------------------------------ snapshot (test mode)
local function r2(V) return math.floor(V * 100 + 0.5) / 100 end
local function snapshot()
	local Rows = {}
	local function attrs(I)
		local A = {}
		for K, V in pairs(I:GetAttributes()) do table.insert(A, K .. "=" .. tostring(V)) end
		table.sort(A)
		local T = CS:GetTags(I)
		table.sort(T)
		return table.concat(A, ",") .. "#" .. table.concat(T, ",")
	end
	local function row(I)
		local S = I:GetFullName() .. "|" .. I.ClassName
		if I:IsA("BasePart") then
			local C = {I.CFrame:GetComponents()}
			for K = 1, 12 do C[K] = r2(C[K]) end
			S ..= "|" .. table.concat(C, ",")
		end
		table.insert(Rows, S .. "|" .. attrs(I))
	end
	row(GH)
	for _, I in ipairs(GH:GetDescendants()) do row(I) end
	row(MarkersRoot)
	for _, I in ipairs(MarkersRoot:GetDescendants()) do row(I) end
	row(NPCs)
	for _, I in ipairs(NPCs:GetDescendants()) do row(I) end
	table.sort(Rows)
	local Tags, Parts = {}, 0
	for _, I in ipairs(workspace:GetDescendants()) do
		if I:IsA("BasePart") then Parts += 1 end
		for _, T in ipairs(CS:GetTags(I)) do Tags[T] = (Tags[T] or 0) + 1 end
	end
	local TL = {}
	for T, N in pairs(Tags) do table.insert(TL, T .. "=" .. N) end
	table.sort(TL)
	table.insert(Rows, "#tags " .. table.concat(TL, ","))
	table.insert(Rows, "#workspace BaseParts " .. Parts)
	table.insert(Rows, "#Map.Foundry " .. attrs(FD))
	local Kids = {}
	for _, C in ipairs(FD:GetChildren()) do table.insert(Kids, C.Name) end
	table.sort(Kids)
	table.insert(Rows, "#Map.Foundry children " .. table.concat(Kids, ","))
	return Rows
end
local function compare(A, B)
	local Diffs, First = 0, {}
	local Set = {}
	for _, S in ipairs(B) do Set[S] = (Set[S] or 0) + 1 end
	for _, S in ipairs(A) do
		if Set[S] and Set[S] > 0 then Set[S] -= 1 else Diffs += 1 if #First < 4 then table.insert(First, "before only: " .. S) end end
	end
	for S, N in pairs(Set) do
		if N > 0 then Diffs += N if #First < 8 then table.insert(First, "after only: " .. S) end end
	end
	return Diffs, First
end

-- ------------------------------------------------------------------ apply / undo
local function locked()
	if RunService:IsRunning() then return "Play is running" end
	local L = SS:GetAttribute("PlayLock")
	if L ~= nil then return "PlayLock is set (" .. tostring(L) .. ")" end
	return nil
end
local function marked()
	local L = {}
	for _, I in ipairs(workspace:GetDescendants()) do
		if I:GetAttribute(ADD) ~= nil then table.insert(L, I) end
	end
	return L
end
-- what apply would refuse on (read-only; plan reports it too)
local function preflight()
	local Lk = locked()
	if Lk then return Lk end
	if FD:GetAttribute(FLAG) ~= nil then return "already applied (" .. FLAG .. " is " .. tostring(FD:GetAttribute(FLAG)) .. ")" end
	local M = marked()
	if #M > 0 then return ("%d instances in workspace still carry %s (undo first)"):format(#M, ADD) end
	if FD:FindFirstChild("ForgeRooms") then return "Map.Foundry.ForgeRooms already exists" end
	local B = trainerMetal()
	if B then return "a trainer_metal model already exists: " .. B:GetFullName() end
	for _, Tag in ipairs({"RenseiInspect", "RenseiMechanism", "RenseiTrial"}) do
		for _, I in ipairs(tagged(Tag)) do
			for _, Piece in ipairs(KIT.Pieces) do
				for K, V in pairs(Piece.Attributes) do
					if (K == "InspectId" or K == "MechanismId" or K == "TrialId") and I:GetAttribute(K) == V then
						return ("%s %s = %s already exists: %s"):format(Tag, K, V, I:GetFullName())
					end
				end
			end
		end
	end
	for _, I in ipairs(tagged("RenseiArea")) do
		if I:GetAttribute("AreaName") == "Silent Forge" then return "a Silent Forge area already exists: " .. I:GetFullName() end
	end
	for _, I in ipairs(tagged("RenseiEnemySpawn")) do
		if I:GetAttribute("EnemyType") == "WardAlchemist" then return "a WardAlchemist spawn already exists: " .. I:GetFullName() end
	end
	if not trainerSpot() then return "no single Metal TrainerSpot marker" end
	local SC = game.StarterPlayer:FindFirstChild("StarterCharacter")
	if not (SC and SC:FindFirstChild("HumanoidRootPart") and SC:FindFirstChildOfClass("Humanoid")) then return "no StarterPlayer.StarterCharacter with a HumanoidRootPart and a Humanoid" end
	local Folder = NPCs:FindFirstChild("Alchemy Trainers")
	if Folder and Folder:FindFirstChild("Metal Alchemist") then return "World.NPCs[\"Alchemy Trainers\"] already has a Metal Alchemist" end
	return nil
end

-- a new piece from the kit (not parented); Src is the MeshPart to clone for a MeshPart
local function makePiece(Piece, Src)
	local P
	if Piece.Class == "MeshPart" then
		P = Src:Clone()
		P:ClearAllChildren()
		for K in pairs(P:GetAttributes()) do P:SetAttribute(K, nil) end
		for _, T in ipairs(CS:GetTags(P)) do CS:RemoveTag(P, T) end
		if Piece.TextureID then P.TextureID = Piece.TextureID end
	elseif Piece.Class == "Part" then
		P = Instance.new("Part")
		P.Shape = Enum.PartType[Piece.Shape]
	else
		error({Refuse = Piece.Path .. " is a " .. tostring(Piece.Class)})
	end
	P.Name = leaf(Piece.Path)
	P.Anchored = Piece.Anchored
	P.Size = sizeOf(Piece)
	P.CFrame = target(Piece)
	P.Color = Color3.new(Piece.Color[1], Piece.Color[2], Piece.Color[3])
	P.Material = Enum.Material[Piece.Material]
	P.MaterialVariant = Piece.MaterialVariant
	P.Transparency, P.Reflectance = Piece.Transparency, Piece.Reflectance
	P.CanCollide, P.CanQuery, P.CanTouch, P.CastShadow = Piece.CanCollide, Piece.CanQuery, Piece.CanTouch, Piece.CastShadow
	for K, V in pairs(Piece.Attributes) do P:SetAttribute(K, V) end
	P:SetAttribute(ADD, true)
	return P
end

local function apply()
	local Why = preflight()
	if Why then return false, Why end
	-- every MeshPart's source first: if one has none, refuse, changing nothing
	local Sources, Report = {}, {}
	for _, Piece in ipairs(KIT.Pieces) do
		if Piece.Class == "MeshPart" then
			local Src, How = meshSource(Piece.MeshId)
			if not Src then return false, Piece.Group .. "/" .. Piece.Path .. " (" .. Piece.MeshId .. "): " .. How end
			Sources[Piece] = Src
			table.insert(Report, Piece.Group .. "/" .. Piece.Path .. " " .. Piece.MeshId:match("%d+$") .. ": " .. How)
		end
	end
	local SC = game.StarterPlayer.StarterCharacter

	local Journal = {}
	local function parent(I, To)
		table.insert(Journal, {"made", I}) -- (Ruling 26: the journal entry before the Parent)
		I.Parent = To
		return I
	end
	local Rec
	pcall(function() Rec = CHS:TryBeginRecording("Foundry forge apply") end)
	local WardAt
	local Ok, Err = pcall(function()
		local Rooms = Instance.new("Model")
		Rooms.Name = "ForgeRooms"
		Rooms:SetAttribute(ADD, true)
		parent(Rooms, FD)
		local Groups = {}
		for _, Name in ipairs({"SilentForge", "ForgeFloor"}) do
			local M = Instance.new("Model")
			M.Name = Name
			M:SetAttribute(ADD, true)
			Groups[Name] = parent(M, Rooms)
		end
		-- the pieces, shallowest first; a container on a path is made from its Models entry
		local Made = {} -- ["Group|Path"] = instance (the first piece of that path)
		local function container(Group, Path)
			if Path == nil then return Groups[Group] end
			local Key = Group .. "|" .. Path
			if Made[Key] then return Made[Key] end
			local Def = Containers[Key]
			if not Def then error({Refuse = Key .. " is neither a piece made before it nor a Models entry"}) end
			if not (Def.Class == "Folder" or Def.Class == "Model") then error({Refuse = Key .. " is a " .. tostring(Def.Class)}) end
			local Under = container(Group, parentPath(Path))
			local C = Instance.new(Def.Class)
			C.Name = leaf(Path)
			for K, V in pairs(Def.Attributes) do C:SetAttribute(K, V) end
			C:SetAttribute(ADD, true)
			Made[Key] = parent(C, Under)
			return C
		end
		local Order = {}
		for I, Piece in ipairs(KIT.Pieces) do
			if Piece.Group == "SilentForge" or Piece.Group == "ForgeFloor" then table.insert(Order, {I, Piece}) end
		end
		table.sort(Order, function(A, B)
			local DA, DB = depth(A[2].Path), depth(B[2].Path)
			if DA ~= DB then return DA < DB end
			return A[1] < B[1]
		end)
		for _, E in ipairs(Order) do
			local Piece = E[2]
			local Under = container(Piece.Group, parentPath(Piece.Path))
			local P = makePiece(Piece, Sources[Piece]) -- (the area box takes the interior's CFrame and Size: target / sizeOf)
			parent(P, Under)
			for _, T in ipairs(Piece.Tags) do CS:AddTag(P, T) end
			Made[Piece.Group .. "|" .. Piece.Path] = Made[Piece.Group .. "|" .. Piece.Path] or P
		end
		-- the Ward spawn, after the other pieces: the first spot whose ray and box pass
		local W = Instance.new("Part")
		local WP = KIT.Ward
		W.Name = leaf(WP.Path)
		W.Shape = Enum.PartType[WP.Shape]
		W.Anchored, W.Size = WP.Anchored, v3(WP.Size)
		W.Color = Color3.new(WP.Color[1], WP.Color[2], WP.Color[3])
		W.Material, W.MaterialVariant = Enum.Material[WP.Material], WP.MaterialVariant
		W.Transparency, W.Reflectance = WP.Transparency, WP.Reflectance
		W.CanCollide, W.CanQuery, W.CanTouch, W.CastShadow = WP.CanCollide, WP.CanQuery, WP.CanTouch, WP.CastShadow
		for K, V in pairs(WP.Attributes) do W:SetAttribute(K, V) end
		W:SetAttribute("EnemyType", "WardAlchemist")
		W:SetAttribute("Weapon", "")
		W:SetAttribute(ADD, true)
		local Tried = {}
		for I, S in ipairs(WARD_SPOTS) do
			local Pass, How = wardSpotTest(S.At, {W})
			if Pass then
				WardAt = ("spot %d, %s, at %s (%s)"):format(I, S.Name, f1(S.At), How)
				W.CFrame = CFrame.new(S.At)
				break
			end
			table.insert(Tried, ("spot %d %s: %s"):format(I, f1(S.At), How))
		end
		if not WardAt then error({Refuse = "no Ward spot passes: " .. table.concat(Tried, "; ")}) end
		if #Tried > 0 then WardAt ..= "; failed first: " .. table.concat(Tried, "; ") end
		parent(W, Groups.SilentForge)
		for _, T in ipairs(WP.Tags) do CS:AddTag(W, T) end

		-- Brannoc
		local Folder = NPCs:FindFirstChild("Alchemy Trainers")
		if not Folder then
			Folder = Instance.new(KIT.Brannoc.FolderClass or "Folder")
			Folder.Name = "Alchemy Trainers"
			Folder:SetAttribute(ADD, true)
			parent(Folder, NPCs)
		end
		local Rig = SC:Clone()
		for _, D in ipairs(Rig:GetDescendants()) do
			if D:IsA("LuaSourceContainer") or D:IsA("PackageLink") then D:Destroy() end
		end
		Rig.Name = "Metal Alchemist"
		for K, V in pairs(KIT.Brannoc.Attributes) do Rig:SetAttribute(K, V) end
		Rig:SetAttribute(ADD, true)
		local Hum = Rig:FindFirstChildOfClass("Humanoid")
		local H = KIT.Brannoc.Humanoid
		Hum.DisplayName = H.DisplayName
		Hum.DisplayDistanceType = Enum.HumanoidDisplayDistanceType[H.DisplayDistanceType]
		Hum.NameDisplayDistance, Hum.HealthDisplayDistance = H.NameDisplayDistance, H.HealthDisplayDistance
		local Root = Rig:FindFirstChild("HumanoidRootPart")
		Root.Anchored = true
		Rig:PivotTo(BRANNOC_CF * Root.CFrame:Inverse() * Rig:GetPivot())
		-- his props (Group Brannoc), as children of the rig, as in Ye
		local Props = {}
		local function propContainer(Path)
			if Path == nil then return Rig end
			if Props[Path] then return Props[Path] end
			local Def = Containers["Brannoc|" .. Path]
			if not Def then error({Refuse = "Brannoc|" .. Path .. " is not a Models entry"}) end
			local C = Instance.new(Def.Class)
			C.Name = leaf(Path)
			for K, V in pairs(Def.Attributes) do C:SetAttribute(K, V) end
			C:SetAttribute(ADD, true)
			Props[Path] = parent(C, propContainer(parentPath(Path))) -- (inside the rig, which isn't in the place yet)
			return C
		end
		for _, Piece in ipairs(kitPieces("Brannoc")) do
			local P = makePiece(Piece, Sources[Piece])
			parent(P, propContainer(parentPath(Piece.Path)))
			for _, T in ipairs(Piece.Tags) do CS:AddTag(P, T) end
		end
		parent(Rig, Folder)

		table.insert(Journal, {"flag"}) -- (Task 9, Ruling 35: the journal entry before the flag)
		FD:SetAttribute(FLAG, "applied")
	end)
	if not Ok then
		for I = #Journal, 1, -1 do
			local J = Journal[I]
			pcall(function()
				if J[1] == "made" then J[2]:Destroy()
				elseif J[1] == "flag" then FD:SetAttribute(FLAG, nil) end
			end)
		end
		if Rec then pcall(function() CHS:FinishRecording(Rec, Enum.FinishRecordingOperation.Cancel) end) end
		local W = type(Err) == "table" and Err.Refuse or ("error: " .. tostring(Err))
		return false, W .. " (rolled back " .. #Journal .. " steps)"
	end
	if Rec then pcall(function() CHS:FinishRecording(Rec, Enum.FinishRecordingOperation.Commit) end)
	else pcall(function() CHS:SetWaypoint("Foundry forge apply") end) end
	return true, ("applied: %d steps. Ward: %s. Meshes: %s"):format(#Journal, WardAt, table.concat(Report, "; "))
end

local function undo()
	local Lk = locked()
	if Lk then return false, Lk end
	local Tops = {}
	for _, I in ipairs(marked()) do
		if not (I.Parent and I.Parent:GetAttribute(ADD) ~= nil) then table.insert(Tops, I) end
	end
	local Names = {}
	local Rec
	pcall(function() Rec = CHS:TryBeginRecording("Foundry forge undo") end)
	local Ok, Err = pcall(function()
		for _, I in ipairs(Tops) do
			table.insert(Names, I:GetFullName())
			I:Destroy()
		end
		FD:SetAttribute(FLAG, nil)
	end)
	if Rec then pcall(function() CHS:FinishRecording(Rec, Ok and Enum.FinishRecordingOperation.Commit or Enum.FinishRecordingOperation.Cancel) end)
	elseif Ok then pcall(function() CHS:SetWaypoint("Foundry forge undo") end) end
	if not Ok then return false, "error: " .. tostring(Err) end
	return true, ("undone: destroyed %d top-level %s instances [%s]; %s cleared"):format(#Tops, ADD, table.concat(Names, ", "), FLAG)
end

-- ------------------------------------------------------------------ run
local Out = {}
local function count()
	local N = 0
	for _, I in ipairs(workspace:GetDescendants()) do if I:IsA("BasePart") then N += 1 end end
	return N
end
if MODE == "plan" then
	table.insert(Out, ("build_forge plan: %s is %s; kit %s: %d pieces, %d Models; workspace BaseParts %d."):format(FLAG,
		tostring(FD:GetAttribute(FLAG)), KIT.Source, #KIT.Pieces, #KIT.Models, count()))
	table.insert(Out, "  apply would " .. (preflight() and ("REFUSE: " .. preflight()) or "go ahead"))
	for _, Piece in ipairs(KIT.Pieces) do
		local CF, S = target(Piece), sizeOf(Piece)
		local Probe = Instance.new("Part")
		Probe.Size, Probe.CFrame = S, CF
		local Lo, Hi = aabb(Probe)
		Probe:Destroy()
		local Line = ("  %s/%s %s at %s, x %.1f..%.1f z %.1f..%.1f y %.2f..%.2f"):format(Piece.Group, Piece.Path, Piece.Class,
			f1(CF.Position), Lo.X, Hi.X, Lo.Z, Hi.Z, Lo.Y, Hi.Y)
		if Piece.Group == "SilentForge" and Piece.CanCollide and not hasTag(Piece, "RenseiArea") then
			local Fits = Lo.X >= SF_BOX.X0 + INSET and Hi.X <= SF_BOX.X1 - INSET and Lo.Z >= SF_BOX.Z0 + INSET and Hi.Z <= SF_BOX.Z1 - INSET
			Line ..= Fits and " (colliding; fits)" or " (colliding; DOES NOT FIT)"
		end
		if Piece.Class == "MeshPart" then Line ..= "; mesh " .. select(2, meshSource(Piece.MeshId)) end
		table.insert(Out, Line)
	end
	for I, S in ipairs(WARD_SPOTS) do
		local Pass, How = wardSpotTest(S.At, {})
		table.insert(Out, ("  Ward spot %d %s %s: %s (the room as it is now, without the pieces)"):format(I, f1(S.At), S.Name, (Pass and "passes, " or "fails, ") .. How))
	end
	local Spot = trainerSpot()
	local KR = cf(KIT.Brannoc.Root).Position + PROP_SHIFT
	table.insert(Out, ("  Brannoc's root -> %s (Ye root + the prop shift = %s); TrainerSpot %s"):format(f1(BRANNOC_CF.Position), f1(KR), Spot and f1(Spot.Position) or "MISSING"))
elseif MODE == "apply" then
	local Before = count()
	local Ok, Msg = apply()
	if not Ok then return refuse(Msg) end
	local Fails, Head, Lines = checks()
	table.insert(Out, "build_forge apply: " .. Msg)
	table.insert(Out, ("%s; workspace BaseParts %d -> %d"):format(Head, Before, count()))
	for _, L in ipairs(Lines) do table.insert(Out, L) end
elseif MODE == "undo" then
	local Ok, Msg = undo()
	if not Ok then return refuse(Msg) end
	table.insert(Out, "build_forge undo: " .. Msg)
elseif MODE == "check" then
	local Fails, Head, Lines = checks()
	table.insert(Out, "build_forge " .. Head .. " (" .. FLAG .. " is " .. tostring(FD:GetAttribute(FLAG)) .. ")")
	for _, L in ipairs(Lines) do table.insert(Out, L) end
elseif MODE == "test" then
	if FD:GetAttribute(FLAG) ~= nil then return refuse("applied; undo first or run check") end
	local Before = snapshot()
	local Ok, Msg = apply()
	if not Ok then return refuse(Msg) end
	-- (Ruling 26) check runs in a pcall: undo always runs
	local COk, Fails, Head, Lines = pcall(checks)
	if not COk then Head, Lines = "check ERROR: " .. tostring(Fails), {} end
	local UOk, UMsg = undo()
	local SOk, After = pcall(snapshot)
	local Diffs, First = 0, {}
	if SOk then Diffs, First = compare(Before, After) else Diffs, First = -1, {"snapshot ERROR: " .. tostring(After)} end
	table.insert(Out, ("build_forge test: %s %s; %s; round trip %s (%d rows, %d differ)"):format(Msg, Head,
		UOk and UMsg or ("UNDO FAILED: " .. UMsg), Diffs == 0 and "EXACT" or "DIFFERS", #Before, Diffs))
	for _, L in ipairs(Lines) do table.insert(Out, L) end
	for _, L in ipairs(First) do table.insert(Out, "  " .. L) end
else
	return refuse("unknown MODE " .. tostring(MODE))
end
return table.concat(Out, "\n")
